from pathlib import Path
import json,re,hashlib
P=Path(__file__).resolve().parent
sources=json.loads((P/'source.json').read_text());out=[];audit=[]
season="un emploi dont les tâches sont appelées à se répéter chaque année selon une périodicité à peu près fixe, en fonction du rythme des saisons ou des modes de vie collectifs"
transition="Les contrats de travail à durée déterminée valablement conclus avant l'entrée en vigueur de la loi instituant le contrat unique à durée indéterminée, les rémunérations, dépenses et périodes qui s'y rattachent ainsi que les droits et créances nés à leur titre restent soumis aux dispositions antérieures qui leur sont applicables. Le présent article n'autorise pas la conclusion d'un nouveau contrat à durée déterminée."

def replace(text,old,new):
 assert text.count(old)==1,(old[:120],text.count(old))
 return text.replace(old,new)

def paragraph(text,start,new):
 pattern=r'<p[^>]*>'+re.escape(start)+r'.*?</p>'
 result,n=re.subn(pattern,lambda m:'<p>'+new+'</p>',text,flags=re.S)
 assert n==1,(start,n)
 return result

